begin;
set local search_path=public,extensions;
select plan(9);
grant usage on schema extensions to authenticated;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)select('f2390000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','quote-tax-scope239-'||i||'@example.invalid',now(),'{}','{}',now(),now()from generate_series(1,2)i;
insert into public.organizations(id,legal_name,display_name,status,created_by)values('f2391000-0000-4000-8000-000000000001','TEST Provider239','TEST Provider239','ACTIVE','f2390000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status)values('f2392000-0000-4000-8000-000000000001','f2391000-0000-4000-8000-000000000001','f2390000-0000-4000-8000-000000000001','ACTIVE');
insert into public.organization_member_roles(membership_id,role_code)values('f2392000-0000-4000-8000-000000000001','PROVIDER_OWNER');
insert into public.platform_user_roles(user_id,role_code)values('f2390000-0000-4000-8000-000000000002','SUPER_ADMIN');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f2390000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.list_provider_quote_service_tax_policies_v1('f2391000-0000-4000-8000-000000000001','{}')$$,'42501','QUOTE_PROVIDER_SCOPE_DENIED','platform finance authority does not bypass provider tenancy');
select set_config('request.jwt.claims','{"sub":"f2390000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is(public.list_provider_quote_service_tax_policies_v1('f2391000-0000-4000-8000-000000000001','{}'),'[]'::jsonb,'authorized provider with no invitations receives no invented classification');
select throws_ok($$select public.list_provider_quote_service_tax_policies_v1('f2391000-0000-4000-8000-000000000001',null)$$,'22023','INVALID_QUOTE_INVITATION_IDS','NULL list cannot become a broad query');
select throws_ok($$select public.list_provider_quote_service_tax_policies_v1('f2391000-0000-4000-8000-000000000001',array[null::uuid])$$,'22023','INVALID_QUOTE_INVITATION_IDS','NULL element is rejected');
select throws_ok($$select public.list_provider_quote_service_tax_policies_v1('f2391000-0000-4000-8000-000000000001',array_fill('f2393000-0000-4000-8000-000000000001'::uuid,array[101]))$$,'22023','INVALID_QUOTE_INVITATION_IDS','lookup is bounded to one hundred scoped invitations');
select throws_ok($$select public.list_provider_quote_service_tax_policies_v1('f2391000-0000-4000-8000-000000000001',array['f2393000-0000-4000-8000-000000000001'::uuid])$$,'42501','QUOTE_PROVIDER_SCOPE_DENIED','foreign or missing invitation does not expose another request');
reset role;
select ok(not has_function_privilege('authenticated','private.resolve_quote_service_tax_policy_v1(uuid)','EXECUTE'),'raw classification source resolver remains private');
select ok(not has_function_privilege('service_role','public.list_provider_quote_service_tax_policies_v1(uuid,uuid[])','EXECUTE'),'transport role has no tenant lookup API');
select ok(not has_function_privilege('authenticated','public.create_quote_revision_legacy_0156(uuid,jsonb,text,text,uuid)','EXECUTE'),'mature calculation core cannot bypass scoped public admission');
select *from finish();
rollback;
